# Load required libraries
library(readr)
library(dplyr)
library(tidyr)
library(purrr)
library(labelled)

# Define the file paths
file_paths <- c(
  'data/input/wave_one_lsype_young_person_2020.tab',
  'data/input/wave_four_lsype_young_person_2020.tab',
  'data/input/wave_six_lsype_young_person_2020.tab',
  'data/input/wave_seven_lsype_young_person_2020.tab',
  'data/input/ns8_2015_main_interview.tab',
  'data/input/ns9_2022_main_interview.tab'
)

# Load each file into a separate object
wave1 <- read_delim(file_paths[1], delim = '\t')
wave4 <- read_delim(file_paths[2], delim = '\t')
wave6 <- read_delim(file_paths[3], delim = '\t')
wave7 <- read_delim(file_paths[4], delim = '\t')
wave8 <- read_delim(file_paths[5], delim = '\t')
wave9 <- read_delim(file_paths[6], delim = '\t')

# Merge datasets using full_join by NSID
merged_data <- full_join(wave1, wave4, by = 'NSID')
merged_data <- full_join(merged_data, wave6, by = 'NSID')
merged_data <- full_join(merged_data, wave7, by = 'NSID')
merged_data <- full_join(merged_data, wave8, by = 'NSID')
merged_data <- full_join(merged_data, wave9, by = 'NSID')

# Define the mapping for harmonizing educational aims to a 6-category scheme
# NVQ system: 1=Level 1, 2=Level 2, 3=Level 3, 4=Level 4, 5=Level 5, 6=Other/None
# The 6-category scheme is:
# 1 = Level 1 (NVQ 1, Foundation, Other Level 1)
# 2 = Level 2 (NVQ 2, Intermediate GNVQ, GCSE, Other Level 2)
# 3 = Level 3 (NVQ 3, AVCE, A/AS, Other Level 3)
# 4 = Level 4 (NVQ 4, Higher Education)
# 5 = Level 5 (NVQ 5, Higher Degree)
# 6 = Not studying, No detail, Other (level unknown)

# Create a function to harmonize the educational aims
harmonize_educaim <- function(var_name, wave_data) {
  if (!var_name %in% names(wave_data)) {
    return(NULL)
  }

  # Define the mapping rules for each wave
  mapping_rules <- list(
    wave4 = list(
      'w4saim' = c(
        '1.0' = 3, '2.0' = 3, '3.0' = 3, '4.0' = 3,  # NVQ 3, AVCE, A/AS, Other level 3
        '5.0' = 2, '6.0' = 2, '7.0' = 2, '8.0' = 2,  # NVQ 2, Intermediate GNVQ, Other level 2, GCSE
        '9.0' = 1, '10.0' = 1, '11.0' = 1, '12.0' = 6, '13.0' = 6, '14.0' = 6  # NVQ 1, Foundation, Other level 1, Other, No detail, Not studying
      )
    ),
    wave6 = list(
      'W6Saim' = c(
        '1.0' = 5, '2.0' = 5, '3.0' = 4, '4.0' = 4,  # NVQ 5, NVQ 4, Other HE
        '5.0' = 3, '6.0' = 3, '7.0' = 3, '8.0' = 3,  # NVQ 3, AVCE, A/AS, Other level 3
        '9.0' = 2, '10.0' = 2, '11.0' = 2, '12.0' = 1, '13.0' = 1, '14.0' = 6, '15.0' = 6, '16.0' = 6  # NVQ 2, Other level 2, GCSE, NVQ 1, Other level 1, Other (level unknown), No detail, Not studying
      )
    ),
    wave7 = list(
      'W7SAim' = c(
        '1.0' = 1, '2.0' = 1, '3.0' = 2, '4.0' = 2, '5.0' = 2,  # NVQ 1, Other level 1, NVQ 2, GCSE, Other level 2
        '6.0' = 3, '7.0' = 3, '8.0' = 3, '9.0' = 3,  # NVQ 3, A/AS, AVCE, Other level 3
        '10.0' = 4, '11.0' = 5, '12.0' = 4, '13.0' = 5, '14.0' = 6  # NVQ 4, NVQ 5, Other HE, Other (level unknown)
      )
    ),
    wave8 = list(
      'W8VCQUC0J' = c(  # NVQ/SVQ - Level 3-5
        '1.0' = 3, '0.0' = 6
      ),
      'W8ACQUC0A' = c(  # University Higher Degree
        '1.0' = 5, '0.0' = 6
      ),
      'W8ACQUC0B' = c(  # First degree level qualification
        '1.0' = 4, '0.0' = 6
      ),
      'W8ACQUC0C' = c(  # Diploma in higher education
        '1.0' = 4, '0.0' = 6
      ),
      'W8ACQUC0F' = c(  # A Level
        '1.0' = 3, '0.0' = 6
      ),
      'W8ACQUC0I' = c(  # AS Level
        '1.0' = 3, '0.0' = 6
      ),
      'W8ACQUC0L' = c(  # GCSE
        '1.0' = 2, '0.0' = 6
      ),
      'W8ACQUC0M' = c(  # Standard Grade / Lower (Scotland)
        '1.0' = 2, '0.0' = 6
      ),
      'W8VCQUC0C' = c(  # Basic skills
        '1.0' = 1, '0.0' = 6
      ),
      'W8VCQUC0D' = c(  # Entry level qualifications (Wales)
        '1.0' = 1, '0.0' = 6
      )
    ),
    wave9 = list(
      'W9ACQUC0A' = c(  # Doctorate or equivalent
        '1.0' = 5, '2.0' = 6
      ),
      'W9ACQUC0B' = c(  # Masters or equivalent
        '1.0' = 4, '2.0' = 6
      ),
      'W9ACQUC0C' = c(  # Undergraduate or equivalent
        '1.0' = 4, '2.0' = 6
      ),
      'W9ACQUC0D' = c(  # Post-graduate Diplomas and Certificates
        '1.0' = 4, '2.0' = 6
      ),
      'W9ACQUC0E' = c(  # Diplomas in higher education and other higher education qualifications
        '1.0' = 4, '2.0' = 6
      ),
      'W9ACQUC0F' = c(  # Teaching qualifications for schools or further education (below degree level)
        '1.0' = 3, '2.0' = 6
      ),
      'W9ACQUC0G' = c(  # A/AS Levels or equivalent
        '1.0' = 3, '2.0' = 6
      ),
      'W9ACQUC0H' = c(  # Grade A-C, Level 4-9
        '1.0' = 2, '2.0' = 6
      ),
      'W9ACQUC0I' = c(  # Grade D-G, Level 1-3
        '1.0' = 1, '2.0' = 6
      ),
      'W9VCQUC0C' = c(  # Level 4 or 5
        '1.0' = 5, '2.0' = 6
      ),
      'W9VCQUC0D' = c(  # Level 3
        '1.0' = 3, '2.0' = 6
      ),
      'W9VCQUC0E' = c(  # Level 2
        '1.0' = 2, '2.0' = 6
      ),
      'W9VCQUC0F' = c(  # Level 1
        '1.0' = 1, '2.0' = 6
      )
    )
  )

  # Extract the relevant wave and variable name
  wave <- substr(var_name, 1, 1)
  var <- substr(var_name, 2, nchar(var_name))

  # If the variable is not in the mapping rules for the wave, return NULL
  if (!(wave %in% names(mapping_rules)) || !(var %in% names(mapping_rules[[wave]]))) {
    return(NULL)
  }

  # Apply the mapping rules
  mapping <- mapping_rules[[wave]][[var]]
  result <- wave_data[[var_name]]

  # Convert missing values to standard codes
  result[result < -1] <- -3

  # Apply the mapping
  result <- recode(result, !!!mapping)

  # Replace non-applicable or missing values
  result[is.na(result)] <- 6

  return(result)
}

# Create the educational aims variables for each wave
ages <- c(17, 19, 20, 25, 32)
educaim_vars <- c('educaim17', 'educaim19', 'educaim20', 'educaim25', 'educaim32')

# Function to create and map the educational aims variables
create_educaim <- function(wave_data, age, var_name) {
  if (age == 17) {
    # For wave 4 (age 17), use w4saim
    wave_data[[var_name]] <- harmonize_educaim('w4saim', wave4)
  } else if (age == 19) {
    # For wave 6 (age 19), use W6Saim
    wave_data[[var_name]] <- harmonize_educaim('W6Saim', wave6)
  } else if (age == 20) {
    # For wave 7 (age 20), use W7SAim
    wave_data[[var_name]] <- harmonize_educaim('W7SAim', wave7)
  } else if (age == 25) {
    # For wave 8 (age 25), derive from W8* variables
    wave_data[[var_name]] <- harmonize_educaim('W8VCQUC0J', wave8)
    wave_data[[var_name]][wave_data[[var_name]] == 6] <- 6
    wave_data[[var_name]][wave_data[[var_name]] == 3] <- 3
    wave_data[[var_name]][wave_data[[var_name]] == 4] <- 4
    wave_data[[var_name]][wave_data[[var_name]] == 5] <- 5

    # Check for higher education qualifications
    for (acq_var in c('W8ACQUC0A', 'W8ACQUC0B', 'W8ACQUC0C')) {
      if (acq_var %in% names(wave_data) && wave_data[[acq_var]] == 1) {
        wave_data[[var_name]][wave_data[[acq_var]] == 1] <- 4  # Higher education
      }
    }
    # Check for level 3 qualifications
    for (acq_var in c('W8ACQUC0F', 'W8ACQUC0I')) {
      if (acq_var %in% names(wave_data) && wave_data[[acq_var]] == 1) {
        wave_data[[var_name]][wave_data[[acq_var]] == 1] <- 3  # Level 3
      }
    }
    # Check for level 2 qualifications
    if ('W8ACQUC0L' %in% names(wave_data) && wave_data[['W8ACQUC0L']] == 1) {
      wave_data[[var_name]][wave_data[['W8ACQUC0L']] == 1] <- 2  # Level 2
    }
    # Check for level 1 qualifications
    if ('W8VCQUC0C' %in% names(wave_data) && wave_data[['W8VCQUC0C']] == 1) {
      wave_data[[var_name]][wave_data[['W8VCQUC0C']] == 1] <- 1  # Level 1
    }
    if ('W8VCQUC0D' %in% names(wave_data) && wave_data[['W8VCQUC0D']] == 1) {
      wave_data[[var_name]][wave_data[['W8VCQUC0D']] == 1] <- 1  # Level 1
    }

  } else if (age == 32) {
    # For wave 9 (age 32), derive from W9* variables
    wave_data[[var_name]] <- 6  # Default to not studying

    # Check for level 5 qualifications (Doctorate)
    if ('W9ACQUC0A' %in% names(wave_data) && wave_data[['W9ACQUC0A']] == 1) {
      wave_data[[var_name]][wave_data[['W9ACQUC0A']] == 1] <- 5
    }
    # Check for level 4 qualifications (Masters, Undergraduate, etc.)
    for (acq_var in c('W9ACQUC0B', 'W9ACQUC0C', 'W9ACQUC0D', 'W9ACQUC0E')) {
      if (acq_var %in% names(wave_data) && wave_data[[acq_var]] == 1) {
        wave_data[[var_name]][wave_data[[acq_var]] == 1] <- 4
      }
    }
    # Check for level 3 qualifications
    if ('W9ACQUC0F' %in% names(wave_data) && wave_data[['W9ACQUC0F']] == 1) {
      wave_data[[var_name]][wave_data[['W9ACQUC0F']] == 1] <- 3
    }
    if ('W9ACQUC0G' %in% names(wave_data) && wave_data[['W9ACQUC0G']] == 1) {
      wave_data[[var_name]][wave_data[['W9ACQUC0G']] == 1] <- 3
    }
    # Check for level 2 qualifications
    if ('W9ACQUC0H' %in% names(wave_data) && wave_data[['W9ACQUC0H']] == 1) {
      wave_data[[var_name]][wave_data[['W9ACQUC0H']] == 1] <- 2
    }
    # Check for level 1 qualifications
    if ('W9ACQUC0I' %in% names(wave_data) && wave_data[['W9ACQUC0I']] == 1) {
      wave_data[[var_name]][wave_data[['W9ACQUC0I']] == 1] <- 1
    }
    # Check for vocational qualifications
    for (voc_var in c('W9VCQUC0C', 'W9VCQUC0D', 'W9VCQUC0E', 'W9VCQUC0F')) {
      if (voc_var %in% names(wave_data) && wave_data[[voc_var]] == 1) {
        level <- substr(voc_var, 9, 9)
        wave_data[[var_name]][wave_data[[voc_var]] == 1] <- level
      }
    }
  }

  # Ensure all values are within the 1-6 range
  wave_data[[var_name]][wave_data[[var_name]] < 1 | wave_data[[var_name]] > 6] <- 6

  return(wave_data)
}

# Create the educational aims variables for each age
for (i in 1:length(ages)) {
  age <- ages[i]
  var_name <- educaim_vars[i]

  if (age == 17) {
    merged_data <- create_educaim(merged_data, age, var_name)
  } else if (age == 19) {
    merged_data <- create_educaim(merged_data, age, var_name)
  } else if (age == 20) {
    merged_data <- create_educaim(merged_data, age, var_name)
  } else if (age == 25) {
    merged_data <- create_educaim(merged_data, age, var_name)
  } else if (age == 32) {
    merged_data <- create_educaim(merged_data, age, var_name)
  }
}

# Create the labels for the educational aims variables
educaim_labels <- c(
  '1' = 'NVQ Level 1 or equivalent',
  '2' = 'NVQ Level 2 or equivalent',
  '3' = 'NVQ Level 3 or equivalent',
  '4' = 'NVQ Level 4 or equivalent (Higher Education)',
  '5' = 'NVQ Level 5 or equivalent (Higher Degree)',
  '6' = 'Not studying or no detail'
)

# Apply labels to each educaim variable
for (var in educaim_vars) {
  if (var %in% names(merged_data)) {
    merged_data[[var]] <- factor(merged_data[[var]], levels = 1:6, labels = educaim_labels)
  }
}

# Select only the NSID and educaim variables for the output
output_data <- merged_data %>% select(NSID, all_of(educaim_vars))

# Write the output to a CSV file
write_csv(output_data, 'data/output/cleaned_data.csv')

