arguments.rscript:
# Load required libraries
library(readr)
library(dplyr)

# Define the file paths
file_paths <- c(
  'data/input/wave_one_lsype_young_person_2020.tab',
  'data/input/wave_four_lsype_young_person_2020.tab',
  'data/input/wave_six_lsype_young_person_2020.tab',
  'data/input/wave_seven_lsype_young_person_2020.tab',
  'data/input/ns8_2015_main_interview.tab',
  'data/input/ns9_2022_main_interview.tab'
)

# Load each file into a separate object
wave1 <- read_delim(file_paths[1], delim = '\t')
wave4 <- read_delim(file_paths[2], delim = '\t')
wave6 <- read_delim(file_paths[3], delim = '\t')
wave7 <- read_delim(file_paths[4], delim = '\t')
wave8 <- read_delim(file_paths[5], delim = '\t')
wave9 <- read_delim(file_paths[6], delim = '\t')

# Merge datasets using full_join by NSID
merged_data <- full_join(wave1, wave4, by = 'NSID')
merged_data <- full_join(merged_data, wave6, by = 'NSID')
merged_data <- full_join(merged_data, wave7, by = 'NSID')
merged_data <- full_join(merged_data, wave8, by = 'NSID')
merged_data <- full_join(merged_data, wave9, by = 'NSID')

# Define mappings for educational aims
mapping_w4saim <- c(
  '1.0' = 3, '2.0' = 3, '3.0' = 3, '4.0' = 3,  # NVQ 3, AVCE, A/AS, Other level 3
  '5.0' = 2, '6.0' = 2, '7.0' = 2, '8.0' = 2,  # NVQ 2, Intermediate GNVQ, Other level 2, GCSE
  '9.0' = 1, '10.0' = 1, '11.0' = 1,           # NVQ 1, Foundation, Other level 1
  '-999:14.0' = 6                                 # Other missing values, no detail, not studying
)

mapping_W6Saim <- c(
  '1.0' = 5, '2.0' = 5, '3.0' = 4, '4.0' = 4,  # NVQ 5, NVQ 4, Other HE
  '5.0' = 3, '6.0' = 3, '7.0' = 3, '8.0' = 3,  # NVQ 3, AVCE, A/AS, Other level 3
  '9.0' = 2, '10.0' = 2, '11.0' = 2,           # NVQ 2, Other level 2, GCSE
  '12.0' = 1, '13.0' = 1,                      # NVQ 1, Other level 1
  '-999:16.0' = 6                                # Other missing values, no detail, not studying
)

mapping_W7SAim <- c(
  '1.0' = 1, '2.0' = 1, '3.0' = 2, '4.0' = 2, '5.0' = 2,  # NVQ 1, Other level 1, NVQ 2, GCSE, Other level 2
  '6.0' = 3, '7.0' = 3, '8.0' = 3, '9.0' = 3,            # NVQ 3, A/AS, AVCE, Other level 3
  '10.0' = 4, '11.0' = 5, '12.0' = 4, '13.0' = 5,        # NVQ 4, NVQ 5, Other HE
  '-94.0' = 6, '14.0' = 6, '-999:99.0' = 6              # Not applicable, Other (level unknown), missing values
)

# Create a function to map and assign educaim variables
assign_educaim <- function(data, wave_data, var_name, mapping, age) {
  if (var_name %in% names(wave_data)) {
    wave_data[[paste0('educaim', age)]] <- recode(wave_data[[var_name]], !!!mapping)
    wave_data[[paste0('educaim', age)]][is.na(wave_data[[paste0('educaim', age)]])] <- 6
  } else {
    wave_data[[paste0('educaim', age)]] <- 6
  }
  return(left_join(data, wave_data %>% select(NSID, paste0('educaim', age)), by = 'NSID'))
}

# Assign educaim17 from wave4
merged_data <- assign_educaim(merged_data, wave4, 'w4saim', mapping_w4saim, 17)

# Assign educaim19 from wave6
merged_data <- assign_educaim(merged_data, wave6, 'W6Saim', mapping_W6Saim, 19)

# Assign educaim20 from wave7
merged_data <- assign_educaim(merged_data, wave7, 'W7SAim', mapping_W7SAim, 20)

# For educaim25, derive from wave8 variables
wave8$educaim25 <- 6  # Default value
if ('W8VCQUC0J' %in% names(wave8)) {
  wave8$educaim25[wave8$W8VCQUC0J == 1] <- 3
}
for (acq_var in c('W8ACQUC0A', 'W8ACQUC0B', 'W8ACQUC0C')) {
  if (acq_var %in% names(wave8)) {
    wave8$educaim25[wave8[[acq_var]] == 1] <- 4
  }
}
for (acq_var in c('W8ACQUC0F', 'W8ACQUC0I')) {
  if (acq_var %in% names(wave8)) {
    wave8$educaim25[wave8[[acq_var]] == 1] <- 3
  }
}
if ('W8ACQUC0L' %in% names(wave8)) {
  wave8$educaim25[wave8$W8ACQUC0L == 1] <- 2
}
if ('W8VCQUC0C' %in% names(wave8)) {
  wave8$educaim25[wave8$W8VCQUC0C == 1] <- 1
}
if ('W8VCQUC0D' %in% names(wave8)) {
  wave8$educaim25[wave8$W8VCQUC0D == 1] <- 1
}
merged_data <- left_join(merged_data, wave8 %>% select(NSID, educaim25), by = 'NSID')

# For educaim32, derive from wave9 variables
wave9$educaim32 <- 6  # Default value
if ('W9ACQUC0A' %in% names(wave9)) {
  wave9$educaim32[wave9$W9ACQUC0A == 1] <- 5
}
for (acq_var in c('W9ACQUC0B', 'W9ACQUC0C', 'W9ACQUC0D', 'W9ACQUC0E')) {
  if (acq_var %in% names(wave9)) {
    wave9$educaim32[wave9[[acq_var]] == 1] <- 4
  }
}
if ('W9ACQUC0F' %in% names(wave9)) {
  wave9$educaim32[wave9$W9ACQUC0F == 1] <- 3
}
if ('W9ACQUC0G' %in% names(wave9)) {
  wave9$educaim32[wave9$W9ACQUC0G == 1] <- 3
}
if ('W9ACQUC0H' %in% names(wave9)) {
  wave9$educaim32[wave9$W9ACQUC0H == 1] <- 2
}
if ('W9ACQUC0I' %in% names(wave9)) {
  wave9$educaim32[wave9$W9ACQUC0I == 1] <- 1
}
merged_data <- left_join(merged_data, wave9 %>% select(NSID, educaim32), by = 'NSID')

# Create labels for the educational aims variables
educaim_labels <- c(
  '1' = 'NVQ Level 1 or equivalent',
  '2' = 'NVQ Level 2 or equivalent',
  '3' = 'NVQ Level 3 or equivalent',
  '4' = 'NVQ Level 4 or equivalent (Higher Education)',
  '5' = 'NVQ Level 5 or equivalent (Higher Degree)',
  '6' = 'Not studying or no detail'
)

# Apply labels to each educaim variable
educaim_vars <- c('educaim17', 'educaim19', 'educaim20', 'educaim25', 'educaim32')
for (var in educaim_vars) {
  if (var %in% names(merged_data)) {
    merged_data[[var]] <- factor(merged_data[[var]], levels = 1:6, labels = educaim_labels)
  }
}

# Ensure all educaim variables exist in merged_data
for (var in educaim_vars) {
  if (!(var %in% names(merged_data))) {
    merged_data[[var]] <- 6
    merged_data[[var]] <- factor(merged_data[[var]], levels = 1:6, labels = educaim_labels)
  }
}

# Select only the NSID and educaim variables for the output
output_data <- merged_data %>% select(NSID, all_of(educaim_vars))

# Write the output to a CSV file
write_csv(output_data, 'data/output/cleaned_data.csv')

