wave9 <- read_delim('data/input/ns9_2022_main_interview.tab', delim = '\\t')

# Get all unique NSIDs from wave1 to ensure we have all participants
all_nsids <- unique(wave1$NSID)

# Create base dataset with all NSIDs and default educaim values
base_data <- data.frame(
  NSID = all_nsids,
