)

# Function to map values according to the scheme
map_educaim_value <- function(x, mapping) {
  if (!is.numeric(x)) return(6)

  # Convert to character for matching
  x_char <- as.character(x)

  # Find matches in mapping
  matches <- x_char %in% names(mapping)
  if (any(matches)) {
    return(mapping[x_char[matches]])
  }
  return(6)
}

# Mapping definitions
mapping_w4saim <- setNames(c(
  3, 3, 3, 3,  # 1.0-4.0
  2, 2, 2, 2,  # 5.0-8.0
  1, 1, 1,     # 9.0-11.0
