wave8 <- read_delim('data/input/ns8_2015_main_interview.tab', delim = '\t')
wave9 <- read_delim('data/input/ns9_2022_main_interview.tab', delim = '\t')

# Get all unique NSIDs from wave1
all_nsids <- unique(wave1$NSID)

# Create complete dataset with all NSIDs and default educaim values
complete_data <- data.frame(
  NSID = all_nsids,
  educaim17 = integer(),
  educaim19 = integer(),
  educaim20 = integer(),
  educaim25 = integer(),
  educaim32 = integer()
)

# Initialize all educaim variables to 6 (Not studying or no detail)
complete_data$educaim17 <- 6
complete_data$educaim19 <- 6
complete_data$educaim20 <- 6
complete_data$educaim25 <- 6
complete_data$educaim32 <- 6

# Function to map values
map_educaim <- function(x, mapping) {
  if (!is.numeric(x)) return(6)

  x_char <- as.character(x)
  if (x_char %in% names(mapping)) {
    return(mapping[[x_char]])
  }
  return(6)
}

# Mapping for wave4 (age 17)
mapping_w4saim <- list(
  '1.0' = 3, '2.0' = 3, '3.0' = 3, '4.0' = 3,  # NVQ 3, AVCE, A/AS, Other level 3
  '5.0' = 2, '6.0' = 2, '7.0' = 2, '8.0' = 2,  # NVQ 2, Intermediate GNVQ, Other level 2, GCSE
  '9.0' = 1, '10.0' = 1, '11.0' = 1,           # NVQ 1, Foundation, Other level 1
  '-999.0' = 6, '12.0' = 1, '13.0' = 1, '14.0' = 6  # Missing values, Other level 1, Not studying
)

# Mapping for wave6 (age 19)
mapping_W6Saim <- list(
  '1.0' = 5, '2.0' = 5, '3.0' = 4, '4.0' = 4,  # NVQ 5, NVQ 4, Other HE
  '5.0' = 3, '6.0' = 3, '7.0' = 3, '8.0' = 3,  # NVQ 3, AVCE, A/AS, Other level 3
  '9.0' = 2, '10.0' = 2, '11.0' = 2,           # NVQ 2, Other level 2, GCSE
  '12.0' = 1, '13.0' = 1,                      # NVQ 1, Other level 1
  '-999.0' = 6, '14.0' = 6, '15.0' = 6, '16.0' = 6  # Missing values, Other (level unknown), No detail, Not studying
)

# Mapping for wave7 (age 20)
mapping_W7SAim <- list(
  '1.0' = 1, '2.0' = 1, '3.0' = 2, '4.0' = 2, '5.0' = 2,  # NVQ 1, Other level 1, NVQ 2, GCSE, Other level 2
  '6.0' = 3, '7.0' = 3, '8.0' = 3, '9.0' = 3,            # NVQ 3, A/AS, AVCE, Other level 3
  '10.0' = 4, '11.0' = 5, '12.0' = 4, '13.0' = 5,        # NVQ 4, NVQ 5, Other HE
  '-94.0' = 6, '14.0' = 6, '-999.0' = 6                # Not applicable, Other (level unknown), missing values
)

# Process wave4 data (age 17)
if ('w4saim' %in% names(wave4)) {
  wave4$educaim17 <- sapply(wave4$w4saim, function(x) map_educaim(x, mapping_w4saim))
  complete_data <- left_join(complete_data, wave4[, c('NSID', 'educaim17')], by = 'NSID')
}

# Process wave6 data (age 19)
if ('W6Saim' %in% names(wave6)) {
  wave6$educaim19 <- sapply(wave6$W6Saim, function(x) map_educaim(x, mapping_W6Saim))
  complete_data <- left_join(complete_data, wave6[, c('NSID', 'educaim19')], by = 'NSID')
}

# Process wave7 data (age 20)
if ('W7SAim' %in% names(wave7)) {
  wave7$educaim20 <- sapply(wave7$W7SAim, function(x) map_educaim(x, mapping_W7SAim))
  complete_data <- left_join(complete_data, wave7[, c('NSID', 'educaim20')], by = 'NSID')
}

# Process wave8 data (age 25)
if ('W8VCQUC0J' %in% names(wave8)) {
  wave8$educaim25 <- 6
  wave8$educaim25[wave8$W8VCQUC0J == 1] <- 3  # NVQ Level 3-5

  # Higher education qualifications
  for (acq_var in c('W8ACQUC0A', 'W8ACQUC0B', 'W8ACQUC0C')) {
    if (acq_var %in% names(wave8)) {
      wave8$educaim25[wave8[[acq_var]] == 1] <- 4
    }
  }

  # Level 3 qualifications
  for (acq_var in c('W8ACQUC0F', 'W8ACQUC0I')) {
    if (acq_var %in% names(wave8)) {
      wave8$educaim25[wave8[[acq_var]] == 1] <- 3
    }
  }

  # Level 2 qualifications
  if ('W8ACQUC0L' %in% names(wave8)) {
    wave8$educaim25[wave8$W8ACQUC0L == 1] <- 2
  }

  # Level 1 qualifications
  if ('W8VCQUC0C' %in% names(wave8)) {
    wave8$educaim25[wave8$W8VCQUC0C == 1] <- 1
  }
  if ('W8VCQUC0D' %in% names(wave8)) {
    wave8$educaim25[wave8$W8VCQUC0D == 1] <- 1
  }

  complete_data <- left_join(complete_data, wave8[, c('NSID', 'educaim25')], by = 'NSID')
}

# Process wave9 data (age 32)
if ('W9ACQUC0A' %in% names(wave9)) {
  wave9$educaim32 <- 6
  wave9$educaim32[wave9$W9ACQUC0A == 1] <- 5  # Doctorate

  # Level 4 qualifications
  for (acq_var in c('W9ACQUC0B', 'W9ACQUC0C', 'W9ACQUC0D', 'W9ACQUC0E')) {
    if (acq_var %in% names(wave9)) {
      wave9$educaim32[wave9[[acq_var]] == 1] <- 4
    }
  }

  # Level 3 qualifications
  if ('W9ACQUC0F' %in% names(wave9)) {
    wave9$educaim32[wave9$W9ACQUC0F == 1] <- 3
  }
  if ('W9ACQUC0G' %in% names(wave9)) {
    wave9$educaim32[wave9$W9ACQUC0G == 1] <- 3
  }

  # Level 2 qualifications
  if ('W9ACQUC0H' %in% names(wave9)) {
    wave9$educaim32[wave9$W9ACQUC0H == 1] <- 2
  }

  # Level 1 qualifications
  if ('W9ACQUC0I' %in% names(wave9)) {
    wave9$educaim32[wave9$W9ACQUC0I == 1] <- 1
  }

  complete_data <- left_join(complete_data, wave9[, c('NSID', 'educaim32')], by = 'NSID')
}

# Create factor levels for educaim variables
educaim_labels <- c(
  '1' = 'NVQ Level 1 or equivalent',
  '2' = 'NVQ Level 2 or equivalent',
  '3' = 'NVQ Level 3 or equivalent',
