# Load required libraries
library(readr)
library(dplyr)

# Load all files
wave1 <- read_delim('data/input/wave_one_lsype_young_person_2020.tab', delim = '\t')
wave4 <- read_delim('data/input/wave_four_lsype_young_person_2020.tab', delim = '\t')
wave6 <- read_delim('data/input/wave_six_lsype_young_person_2020.tab', delim = '\t')
wave7 <- read_delim('data/input/wave_seven_lsype_young_person_2020.tab', delim = '\t')
wave8 <- read_delim('data/input/ns8_2015_main_interview.tab', delim = '\t')
wave9 <- read_delim('data/input/ns9_2022_main_interview.tab', delim = '\t')

# Get all unique NSIDs from wave1
all_nsids <- unique(wave1$NSID)

# Create base dataset with all NSIDs
complete_data <- data.frame(NSID = all_nsids)

# Function to create educaim variables
create_educaim <- function(data, age_var, age) {
  # Default value is 6 (Not studying or no detail)
  educaim_name <- paste0('educaim', age)

  # Create a new column with default value
  data[[educaim_name]] <- 6

  # If we have the relevant variable, map it
  if (age == 17 && 'w4saim' %in% names(data)) {
    # Mapping for age 17
    mapping <- c('1.0'=3, '2.0'=3, '3.0'=3, '4.0'=3,  # NVQ 3
                 '5.0'=2, '6.0'=2, '7.0'=2, '8.0'=2,  # NVQ 2
                 '9.0'=1, '10.0'=1, '11.0'=1,        # NVQ 1
                 '-999.0'=6, '12.0'=1, '13.0'=1, '14.0'=6)  # Missing/other

    data$educaim17 <- as.numeric(
      recode(data$w4saim, !!!mapping)
    )
    data$educaim17[is.na(data$educaim17)] <- 6
  }
  else if (age == 19 && 'W6Saim' %in% names(data)) {
    # Mapping for age 19
    mapping <- c('1.0'=5, '2.0'=5, '3.0'=4, '4.0'=4,  # NVQ 5/4
                 '5.0'=3, '6.0'=3, '7.0'=3, '8.0'=3,  # NVQ 3
                 '9.0'=2, '10.0'=2, '11.0'=2,        # NVQ 2
                 '12.0'=1, '13.0'=1,                 # NVQ 1
                 '-999.0'=6, '14.0'=6, '15.0'=6, '16.0'=6)  # Missing/other

    data$educaim19 <- as.numeric(
      recode(data$W6Saim, !!!mapping)
    )
